// #b950c1450cef01f561ab010f — кандидата можно привязать только к АКТИВНОЙ версии симуляции.
// Роль: business (מנהל חשבון, бизнес testim). Письма не отправляются: create_candidate только создаёт запись и
// ссылку (link_created); send-candidate-invite не вызывается.
// Данные: симуляции в статусах טיוטה / ממתינה לאישור / גרסה קודמת / לא פעילה / פעילה берутся из бизнеса во время
// прогона (созданы при ручной проверке, статусы draft/pending/previous_version необратимы). Позитивная проверка
// создаёт кандидата «QA-AUTO-…» (неудаляемый, расходует квоту бизнеса) — поэтому тест помечен @data.
import * as path from 'path';
import { test, expect } from '@playwright/test';
import { openWithApi, runStamp } from '../support/api';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

type Sim = { id: string; name: string; status: string; version: number };
const NOT_ACTIVE = ['draft', 'pending_approval', 'previous_version', 'inactive'] as const;

test.describe('Кандидаты — привязка только к активной симуляции (#b950c1450cef01f561ab010f)', () => {
  test('/candidates/new: в списке только активные версии «(גרסה N)» @desktop @prod-safe #b950c1450cef01f561ab010f', async ({ page }) => {
    const simsLoaded = page.waitForResponse((r) => r.url().includes('/rest/v1/simulations') && r.request().method() === 'GET');
    const api = await openWithApi(page, '/candidates/new');
    await simsLoaded;
    const all = (await (await api.get('simulations?select=id,name,status,version')).json()) as Sim[];
    const active = all.filter((s) => s.status === 'active');

    const select = page.getByRole('combobox', { name: 'סימולציה (חובה)' });
    await expect(select).toBeVisible();
    const options = (await select.locator('option').evaluateAll((os) =>
      os.map((o) => ({ value: (o as HTMLOptionElement).value, text: (o.textContent || '').trim() })),
    )).filter((o) => o.value !== '');

    // Источник: «מה רצוי» — «שיוך מועמד אפשרי רק לגרסה פעילה של סימולציה».
    expect(options.map((o) => o.value).sort()).toEqual(active.map((s) => s.id).sort());
    for (const s of active) expect(options.find((o) => o.value === s.id)!.text).toBe(`${s.name} (גרסה ${s.version})`);
    for (const s of all.filter((x) => x.status !== 'active')) expect(options.map((o) => o.value)).not.toContain(s.id);
  });

  test('сервер: create_candidate на неактивные → 400 simulation_not_active; на активную → 200; PATCH на неактивную → 400 simulation_not_assignable, на активную → 200 @desktop @data #b950c1450cef01f561ab010f', async ({ page }) => {
    const api = await openWithApi(page, '/candidates');
    const all = (await (await api.get('simulations?select=id,name,status,version')).json()) as Sim[];
    const active = all.find((s) => s.status === 'active');
    expect(active, 'окружение: в бизнесе нет активной симуляции').toBeTruthy();
    const managerId = await api.userId();
    const stamp = runStamp();
    const fields = (simulation_id: string, suffix: string) => ({
      full_name: `QA-AUTO-${stamp} ${suffix}`,
      phone: '0000000000',
      email: 'qa+at@example.com',
      role_title: 'QA-AUTO נציג מכירות',
      simulation_id,
      assigned_manager_id: managerId,
    });

    for (const status of NOT_ACTIVE) {
      const sim = all.find((s) => s.status === status);
      expect(sim, `окружение: нет симуляции в статусе ${status}`).toBeTruthy();
      const res = await api.rpc('create_candidate', { p_fields: fields(sim!.id, status) });
      expect(res.status(), `create_candidate на ${status} (${sim!.id})`).toBe(400);
      expect(await res.text()).toContain('simulation_not_active');
    }

    const name = fields(active!.id, 'active').full_name;
    const ok = await api.rpc('create_candidate', { p_fields: fields(active!.id, 'active') });
    expect(ok.status(), await ok.text()).toBe(200);
    const [candidate] = (await (await api.get(`candidates?select=id,simulation_id&full_name=eq.${encodeURIComponent(name)}`)).json()) as { id: string; simulation_id: string }[];
    expect(candidate?.simulation_id).toBe(active!.id);
    test.info().annotations.push({ type: 'test-data', description: `candidate ${name} ${candidate.id} (неудаляем, писем нет)` });

    const inactive = all.find((s) => s.status === 'inactive')!;
    const bad = await api.patch(`candidates?id=eq.${candidate.id}`, { simulation_id: inactive.id });
    expect(bad.status()).toBe(400);
    expect(await bad.text()).toContain('simulation_not_assignable');

    const good = await api.patch(`candidates?id=eq.${candidate.id}`, { simulation_id: active!.id });
    expect(good.status(), await good.text()).toBe(200);
    const [still] = (await (await api.get(`candidates?select=simulation_id&id=eq.${candidate.id}`)).json()) as { simulation_id: string }[];
    expect(still.simulation_id).toBe(active!.id);
  });
});
